insert into public.seo_pages (title, slug, path_prefix, status, is_indexed, is_followed, schema_type, meta_title, meta_description, keywords, content_sections, published_at, updated_at)
values (
  'About FixGrid — Championing Repair Over Replacement',
  'about',
  '',
  'published',
  true,
  true,
  'WebPage',
  'About FixGrid | The Open Directory of Local Repair Experts',
  'FixGrid connects consumers with skilled, independent repair technicians to reduce electronic waste, support local trades, and champion the Right to Repair.',
  array['about FixGrid', 'right to repair platform', 'e-waste reduction', 'local repair directory', 'fix rather than replace'],
  '[{"ctas":[{"href":"/search","label":"Explore Directory"}],"type":"compact_hero","eyebrow":"Our Mission","heading":"Fix More. Waste Less.","subtitle":"FixGrid is an independent platform connecting consumers with verified local repair technicians across electronics, appliances, vehicles, and precision instruments."},{"type":"highlights_strip","items":[{"label":"Community","value":"Independent"},{"label":"Right to Repair","value":"100% Champion"},{"label":"Fake Content","value":"0%"}]},{"html":"<h2>Why FixGrid Exists</h2>\n<p>Every year, millions of tons of repairable consumer electronics and household appliances are discarded into landfills. Modern consumer culture has been pushed toward disposable devices with glued batteries, encrypted parts pairing, and nonexistent manufacturer schematics.</p>\n<p>FixGrid was created to restore balance. By providing transparent technical diagnostic guides, realistic component repair cost benchmarks, and a curated directory of skilled local repairers, we make repairing your existing devices easier, faster, and more affordable than buying brand new replacements.</p>\n\n<h3>Our Core Commitments</h3>\n<ul>\n  <li><strong>100% Real, Honest Content:</strong> We never generate fake customer testimonials, fabricated shops, or artificially inflated ratings. Everything on FixGrid is grounded in real engineering facts and verified local businesses.</li>\n  <li><strong>Advocating for the Right to Repair:</strong> We actively support legislation requiring manufacturers to provide public schematics, spare parts, and diagnostic tools to independent repairers and owners.</li>\n  <li><strong>Empowering Local Trades:</strong> Independent repair technicians are the backbone of sustainable local economies. FixGrid provides them with open visibility without exorbitant lead-generation middlemen fees.</li>\n</ul>","type":"rich_text","width":"prose"},{"cta":{"href":"/search","label":"Search Directory"},"body":"Search local technicians by category, opening hours, and service options.","tone":"signal","type":"cta_banner","heading":"Find a verified repair shop near you"}]'::jsonb,
  '2026-09-09T19:36:59.238+00:00',
  now()
)
