insert into public.seo_pages (title, slug, path_prefix, status, is_indexed, is_followed, schema_type, meta_title, meta_description, keywords, content_sections, published_at, updated_at)
values (
  'Refund Policy',
  'refunds',
  '',
  'published',
  true,
  true,
  'WebPage',
  'Refund Policy | FixGrid',
  'FixGrid''s refund policy and dispute resolution guidelines for consumer repair transactions.',
  array['refund policy', 'repair dispute resolution', 'FixGrid refunds'],
  '[{"type":"compact_hero","heading":"Refund Policy & Dispute Resolution","subtitle":"Clear, transparent guidelines on repair warranties and refund processes."},{"html":"<h2>Repair Warranty & Refund Protocols</h2>\n<p>Because independent repair technicians provide physical services and install hardware parts, service warranties and refund terms are governed by the specific service agreement issued by the repair shop at the time of repair.</p>\n<h3>Verified Shop Warranty Guarantee</h3>\n<p>All verified repair shops on FixGrid agree to maintain a minimum 90-day parts and labor warranty on completed repairs. If a repair fails due to defective parts or workmanship within this timeframe, the shop will re-service the device or refund the labor cost.</p>\n<h3>Dispute Resolution</h3>\n<p>If you experience an unresolved dispute with a verified repairer, contact FixGrid support at support@vytron.me with your receipt and service documentation. We will review the case with the repair shop to ensure fair resolution.</p>","type":"rich_text","width":"prose"}]'::jsonb,
  '2026-09-09T19:37:00.34+00:00',
  now()
)
