insert into public.seo_pages (title, slug, path_prefix, status, is_indexed, is_followed, schema_type, meta_title, meta_description, keywords, content_sections, published_at, updated_at)
values (
  'How Verification Works at FixGrid',
  'verification',
  '',
  'published',
  true,
  true,
  'WebPage',
  'How FixGrid Verifies Local Repair Shops | FixGrid',
  'Learn about the rigorous verification standards FixGrid uses to vet independent repair shops, verify technician credentials, and audit warranties.',
  array['verified repair shops', 'repair shop credentials', 'repair certification', 'vetted repair experts', 'FixGrid standards'],
  '[{"ctas":[{"href":"/search","label":"Browse Verified Shops"}],"type":"compact_hero","eyebrow":"Trust & Safety","heading":"How FixGrid Verifies Repair Experts","subtitle":"Every verified badge on FixGrid represents genuine technical credentials, physical bench audits, business licensing, and transparent customer warranties."},{"type":"highlights_strip","items":[{"label":"License verification","value":"100% Audited"},{"label":"Warranty requirement","value":"90+ Days"},{"label":"Fake reviews","value":"Zero Tolerance"}]},{"html":"<h2>Our 4-Step Repairer Vetting Process</h2>\n<p>FixGrid was founded on the belief that consumers deserve honest, transparent, and skilled independent repair services. We strictly reject fake shops and unverified listings. Here is how every verified repair shop is audited:</p>\n\n<h3>1. Physical Location and Business Entity Verification</h3>\n<p>We verify that every listed repairer operates an active commercial repair workshop or certified mobile service van. We review government registration documents, local business operating licenses, and commercial liability insurance policies.</p>\n\n<h3>2. Diagnostic Bench Equipment & Safety Standards</h3>\n<p>Modern micro-electronics and appliance repairs require professional diagnostic equipment. We verify that shops utilize temperature-controlled soldering stations, anti-static (ESD) protection, high-grade microscopes, diagnostic multimeters, and safe lithium-ion battery handling storage containers.</p>\n\n<h3>3. Minimum 90-Day Parts & Labor Warranty Guarantee</h3>\n<p>To qualify for verified status on FixGrid, a repair shop must offer a written warranty of at least 90 days on both replacement parts and technician labor. If a replaced component fails under normal use within the warranty period, the shop guarantees replacement without additional diagnostic charges.</p>\n\n<h3>4. Authentic Review Integrity</h3>\n<p>FixGrid enforces strict review authenticity. Only verified customers who engage repair shops through our directory can submit service ratings. We utilize automated fraud detection and manual audits to permanently remove any fraudulent or incentivized testimonials.</p>","type":"rich_text","width":"prose"},{"type":"faq_accordion","items":[{"answer":"Look for the green ''Verified'' badge next to the shop name. This indicates the business has passed license, insurance, equipment, and warranty audits.","question":"How do I know a shop on FixGrid is truly verified?"},{"answer":"FixGrid investigates all warranty disputes. If a shop refuses to honor their stated warranty terms, their verified badge is suspended.","question":"What happens if a verified shop does not honor their warranty?"}],"title":"Verification Questions"},{"cta":{"href":"/join","label":"Apply to List Your Shop"},"body":"Join our verified directory of trusted local repair shops today.","tone":"signal","type":"cta_banner","heading":"Are you a qualified repair technician?"}]'::jsonb,
  '2026-09-09T19:36:58.863+00:00',
  now()
)
