insert into public.seo_pages (title, slug, path_prefix, status, is_indexed, is_followed, schema_type, meta_title, meta_description, keywords, content_sections, published_at, updated_at)
values (
  'FixGrid 90-Day Warranty Protection & Dispute Resolution',
  'warranty-protection',
  '',
  'published',
  true,
  true,
  'WebPage',
  'FixGrid 90-Day Repair Warranty Protection & Guarantee',
  'Learn how FixGrid''s mandatory 90-day minimum repair warranty protects consumers against component defects and ensures fair service mediation.',
  array['repair warranty guarantee', '90 day repair warranty', 'fixgrid warranty protection', 'dispute resolution repair', 'certified repair guarantee'],
  '[{"ctas":[{"href":"/search","label":"Find Protected Shops"}],"type":"compact_hero","eyebrow":"Customer Assurance","heading":"Guaranteed 90-Day Repair Protection","subtitle":"Every verified repair shop on FixGrid provides a minimum 90-day parts and labor warranty, backed by impartial platform mediation."},{"type":"highlights_strip","items":[{"label":"Minimum Period","value":"90 Days"},{"label":"Coverage","value":"Parts & Labor"},{"label":"Platform Mediation","value":"100% Free"}]},{"html":"<h2>Transparent Warranty Standards You Can Trust</h2>\n<p>Leaving expensive electronics or essential household appliances with a repair shop requires trust. To eliminate uncertainty, FixGrid requires all verified repairers to adhere to standardized warranty protocols.</p>\n\n<h3>What Is Covered Under the 90-Day Warranty</h3>\n<ul>\n  <li><strong>Replacement Component Defects:</strong> If a replaced screen develops touch digitizer glitches, a new battery fails to hold charge, or an HDMI port loses signal within 90 days, the shop will replace the defective part at zero cost to you.</li>\n  <li><strong>Technician Workmanship:</strong> Solder connections, thermal paste application, internal shielding alignment, and adhesive re-bonding are fully guaranteed against failure under standard operating conditions.</li>\n</ul>\n\n<h3>What Is Excluded from Warranty Coverage</h3>\n<p>Warranties cover manufacturing and assembly defects, but do not cover accidental damage occurring after device pickup, including:</p>\n<ul>\n  <li>Physical drop impacts resulting in cracked glass or bent metal chassis</li>\n  <li>Subsequent liquid immersion or moisture exposure</li>\n  <li>Unauthorized third-party teardown or firmware tampering after repair completion</li>\n</ul>\n\n<h3>How Our Dispute Mediation Works</h3>\n<p>If you experience any issue with a completed repair and the shop fails to resolve it promptly, submit your service receipt and diagnostic photos to our dispute team at support@vytron.me. Our technical advisors review bench logs and ensure the shop fulfills their warranty commitment.</p>","type":"rich_text","width":"prose"},{"type":"faq_accordion","items":[{"answer":"Contact the repair shop directly with your digital invoice or receipt. If you encounter any friction, notify FixGrid support with your booking details for immediate escalation.","question":"How do I claim a warranty repair?"},{"answer":"Yes! Many premium verified shops offer 6-month or 1-year warranties on modular screen and battery replacements. The 90-day requirement is our platform baseline.","question":"Can shops offer longer warranties than 90 days?"}],"title":"Warranty Protection FAQs"},{"cta":{"href":"/search","label":"Search Protected Shops"},"body":"Browse certified repair experts with upfront pricing and verified warranties.","tone":"signal","type":"cta_banner","heading":"Book repair with guaranteed warranty protection"}]'::jsonb,
  '2026-09-09T19:37:01.122+00:00',
  now()
)
