insert into public.seo_pages (title, slug, path_prefix, status, is_indexed, is_followed, schema_type, meta_title, meta_description, keywords, content_sections, published_at, updated_at)
values (
  'Appliance Repair Near You',
  'appliances',
  'repair',
  'published',
  true,
  true,
  'Service',
  'Appliance Repair Near You (Mumbai & Major Cities) — Certified Local Shops & Costs',
  'What appliances repairs cost ($90–$460), typical turnaround times, and verified local repair technicians across Mumbai, Delhi, Bengaluru & nearby hubs. Find experts open now.',
  array['appliances repair', 'appliances repair near me', 'appliances repair in mumbai', 'appliances repair cost', 'fix appliances', 'appliances repair technician', 'local appliances service'],
  '[{"ctas":[{"href":"/search?category=appliances","label":"Find appliance shops"}],"type":"compact_hero","eyebrow":"Repair & Diagnostic Guide","heading":"Appliance Repair Near You","subtitle":"Compare local independent shops that fix appliances, review common component failure costs, and find technicians open right now."},{"type":"highlights_strip","items":[{"label":"Typical cost","value":"$90–$460"},{"label":"Turnaround","value":"1–7 days"},{"label":"Common faults","value":"5"}]},{"type":"table_of_contents","title":"On this page"},{"html":"<h2>Is it worth repairing your appliances?</h2>\n\n<p>Most appliances that develop faults can be repaired reliably for a fraction of the cost of buying new. Choosing repair preserves working hardware, prevents unnecessary electronic waste, and supports independent local trade technicians.</p>\n<p>However, transparent advice matters: repair stops making financial sense when a sealed refrigeration system compressor has suffered internal mechanical burnout or the drum bearing housing has cracked on a machine over ten years old. A professional shop will provide an honest pre-repair assessment before proceeding with work.</p>\n<p>Typical repair costs for appliances fall within the <strong>$90–$460</strong> range, with standard turnarounds spanning <strong>1–7 days</strong> depending on whether replacement components are in local inventory or require specialist supply ordering.</p>","type":"rich_text","width":"prose"},{"type":"feature_grid","items":[{"body":"Foreign objects (coins, hairpins, debris) jamming the drain pump impeller, or open-circuit drain motor windings. Pump filter chamber debridement, impeller rotation test, or drain pump motor assembly replacement.","title":"Washing machine will not drain or spin at end of cycle"},{"body":"Heavy dust buildup on exterior condenser coils, failed evaporator fan motor, or defrost system element burnout causing coil icing. Condenser coil pneumatic clearing, defrost thermostat/heater testing, and evaporator fan replacement.","title":"Refrigerator running continuously but cabinet remains warm"},{"body":"Mineral scale blocking spray arm orifices, clogged micro-filter mesh, or restricted water inlet valve. Chemical de-scaling, spray arm dismantling, and inlet solenoid valve replacement.","title":"Dishwasher not cleaning dishes, grit and cloudy film"},{"body":"Restricted lint exhaust ductwork causing safety thermal cutoffs to trip, or open-circuit heating element coil. Exhaust duct pneumatic brushing, airflow CFM verification, and nichrome heating element replacement.","title":"Clothes dryer takes multiple cycles to dry clothing"},{"body":"Drifted platinum RTD temperature sensor probe or cracked bake/broil heating element. Oven cavity temperature probe calibration and heating element replacement.","title":"Oven temperature inaccurate or baking unevenly"}],"title":"Common Symptoms & Technical Causes","columns":3},{"html":"<h2>Realistic Repair Costs & Benchmark Pricing</h2>\n<p>The price table below provides verified industry benchmarks for common appliances repairs. Use these figures to evaluate repair quotes accurately.</p>\n\n<table>\n<thead><tr><th>Fault / Symptom</th><th>Typical Cost Range</th><th>Bench Turnaround</th></tr></thead>\n<tbody><tr><td><strong>Washing machine will not drain or spin at end of cycle</strong></td><td>$90–$230</td><td>1–2 days</td></tr><tr><td><strong>Refrigerator running continuously but cabinet remains warm</strong></td><td>$120–$380</td><td>1–3 days</td></tr><tr><td><strong>Dishwasher not cleaning dishes, grit and cloudy film</strong></td><td>$90–$210</td><td>1–2 days</td></tr><tr><td><strong>Clothes dryer takes multiple cycles to dry clothing</strong></td><td>$90–$220</td><td>1 day</td></tr><tr><td><strong>Oven temperature inaccurate or baking unevenly</strong></td><td>$110–$280</td><td>1–3 days</td></tr></tbody>\n</table>\n<h3>Factors That Influence Repair Quotes</h3>\n<p><strong>1. Component Quality & Origin:</strong> Genuine OEM parts, certified refurbished original modules, and aftermarket grades differ in cost, color calibration, and durability. Always ask your technician which component tier is quoted.</p>\n<p><strong>2. Component-Level Diagnosis:</strong> Technicians who diagnose and micro-solder specific failed resistors, capacitors, or ports save you significant money compared to shops that simply swap out entire expensive sub-assemblies.</p>","type":"rich_text","width":"prose"},{"body":"<ul><li>Locate the model and serial number plate (usually inside door frames or rear access panel)</li><li>Ensure clear, unobstructed physical access to the appliance for in-home visits</li><li>Note the exact error codes shown on digital displays and when the failure occurs in the cycle</li><li>Check home circuit breakers and verify water shutoff valves are accessible</li></ul>","side":"right","type":"text_image","image":{"alt":"A certified repair technician bench prepared for appliances","src":"/images/bench.jpg"},"heading":"Preparation Checklist Before Drop-Off"},{"html":"<h2>How to Choose a Reputable Local Repair Shop</h2>\n<p>Before leaving your appliances with a repair shop, ask these four critical questions:</p>\n<h3>1. What warranty do you provide on parts and labor?</h3>\n<p>Reputable independent repair shops typically offer a 90-day to 1-year written warranty covering both replacement components and bench labor.</p>\n<h3>2. Do you perform diagnostics before charging?</h3>\n<p>Clear diagnostic estimates ensure you are never surprised by unexpected fees. Ask whether initial bench assessment fees apply toward the final repair cost.</p>\n<h3>3. What is your data security policy?</h3>\n<p>For electronic devices storing personal information, ensure the shop has strict confidentiality protocols, does not require unnecessary passwords, and never wipes storage drives without your prior authorization.</p>\n<h3>4. Are turnaround estimates realistic?</h3>\n<p>Confirm whether common parts are on the shelf or need to be ordered, so you have an accurate timeline for pickup.</p>","type":"rich_text","width":"prose"},{"type":"faq_accordion","items":[{"answer":"Most standard repairs range between $90–$460, depending on component availability and whether the fault is a modular replacement or micro-soldering.","question":"How much does appliance repair typically cost?"},{"answer":"Foreign objects (coins, hairpins, debris) jamming the drain pump impeller, or open-circuit drain motor windings. Pump filter chamber debridement, impeller rotation test, or drain pump motor assembly replacement. Expect typical costs around $90–$230 with turnaround of 1–2 days.","question":"How is ''Washing machine will not drain or spin at end of cycle'' fixed?"},{"answer":"Most jobs are completed within 1–7 days. In-stock modular repairs are frequently finished the same day.","question":"How long will the repair take?"},{"answer":"Consider replacement when a sealed refrigeration system compressor has suffered internal mechanical burnout or the drum bearing housing has cracked on a machine over ten years old.","question":"When should I replace rather than repair?"},{"answer":"Under Right to Repair laws in many jurisdictions, third-party repairs do not void manufacturer warranties unless the repair itself directly causes damage to other components.","question":"Does third-party repair void my manufacturer warranty?"},{"answer":"While many shops accept walk-ins, calling ahead or booking online ensures replacement parts are reserved and technician bench time is scheduled immediately.","question":"Do I need to book an appointment in advance?"}],"title":"Frequently Asked Questions"},{"cta":{"href":"/search?category=appliances","label":"Search the local directory"},"body":"Filter by active opening hours, on-site home visits, collection service, and transparent part warranties.","tone":"signal","type":"cta_banner","heading":"Find a verified appliance expert near you"}]'::jsonb,
  '2026-09-09T19:36:13.207+00:00',
  now()
)
